package com.notificationservice.infrastructure.persistence.adapter;import com.notificationservice.domain.model.*;import com.notificationservice.domain.repository.ScheduledNotificationRepository;import com.notificationservice.infrastructure.persistence.mapper.ScheduledPersistenceMapper;import com.notificationservice.infrastructure.persistence.repository.JpaScheduledNotificationRepository;import org.springframework.data.domain.PageRequest;import org.springframework.stereotype.Repository;import java.time.Instant;import java.util.*;@Repository public class ScheduledPersistenceAdapter implements ScheduledNotificationRepository{private final JpaScheduledNotificationRepository r;private final ScheduledPersistenceMapper m;public ScheduledPersistenceAdapter(JpaScheduledNotificationRepository r,ScheduledPersistenceMapper m){this.r=r;this.m=m;}public ScheduledNotification save(ScheduledNotification s){return m.toDomain(r.save(m.toEntity(s)));}public List<ScheduledNotification> findDue(Instant at,int limit){return r.findByStatusAndScheduledAtLessThanEqualOrderByScheduledAt(ScheduledStatus.PENDING,at,PageRequest.of(0,limit)).stream().map(m::toDomain).toList();}}
